// ig-proto, variant p5-mode (stages 2 to 4 pack T06b, plan 4.4): P5's call budget by uniqueness mode and level.
// IG.callBudget = { id, any: { <level id>: units }, require: { <level id>: units } }; an absent or non-positive entry
// is no budget. Without such a table (undefined, null, or the level-keyed shape of v4-p5) the context is unchanged.
import { IG as IG_FZ } from './ig-params.js';

/**
 * @param {any} ctx The SelectContext of a gen-v4 call.
 * @param {any} [table] IG.callBudget by default.
 * @returns {any} ctx itself, or a copy whose igBudget is the call's budget in units (Infinity for none).
 */
export function igModeBudget(ctx, table = IG_FZ.callBudget) {
  if (ctx.igBudget !== undefined || table === undefined || table === null
    || (table.any === undefined && table.require === undefined)) {
    return ctx;
  }
  const v = table[ctx.uniqueness]?.[ctx.target.id];
  return { ...ctx, igBudget: typeof v === 'number' && v > 0 ? v : Infinity };
}
